param([string]$Root=(Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path 'experiment\results\experiment-1-60'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function J($p){if(Test-Path $p){Get-Content -Raw -Encoding UTF8 $p|ConvertFrom-Json}else{$null}}
$d=Join-Path $Root 'SINK-C400-Q3-R1';$l=(J (Join-Path $d 'load-summary.json')).summary;$s=J (Join-Path $d 'stage-final.json');$dr=J (Join-Path $d 'mock-drain-summary.json');$df=J (Join-Path $d 'dispatcher-final.json');$rows=Get-Content (Join-Path $d 'dispatcher-metrics.jsonl')|%{try{$_|ConvertFrom-Json}catch{}}
$dispatchers=[ordered]@{};foreach($n in @('token','ai','storage')){$x=@($rows|?{$_.dispatcher -eq $n -and ($_.PSObject.Properties.Name -contains 'queueDepth')});$f=$df.dispatchers.$n; $dispatchers[$n]=[ordered]@{samples=$x.Count;queuePeak=if($x.Count){($x.queueDepth|Measure-Object -Maximum).Maximum}else{$null};queueFinal=if($x.Count){$x[-1].queueDepth}else{$null};activePeak=if($x.Count){($x.active|Measure-Object -Maximum).Maximum}else{$null};activeFinal=if($x.Count){$x[-1].active}else{$null};queueWaitP50='NOT_AVAILABLE';queueWaitP95='NOT_AVAILABLE';queueWaitP99='NOT_AVAILABLE';queueWaitMaxSeconds=if($f.'queue.wait'.measurements){($f.'queue.wait'.measurements|?{$_.statistic -eq 'MAX'}).value}else{$null};deadlinePhases='NOT_AVAILABLE';errorSamples=(@($rows|?{$_.dispatcher -eq $n -and ($_.PSObject.Properties.Name -contains 'error')}).Count)}}
$out=$l.outcomeCounts;$result=[ordered]@{experiment='Exp160';controlReuse=$true;controlRun='C600-100-R1';control=[ordered]@{acceptedPerLoadSecond=134.27;http200P95=13265;http500=1873;timeout=66;connectionError=0};sink=[ordered]@{runId='SINK-C400-Q3';attempts=$l.startedRequests;accepted=$out.HTTP_200_ACCEPTED;acceptedPerLoadSecond=[math]::Round($out.HTTP_200_ACCEPTED/30,2);successRate=[math]::Round(100*$out.HTTP_200_ACCEPTED/$l.startedRequests,2);http200P50=$l.latencyByOutcome.HTTP_200_ACCEPTED.p50;http200P95=$l.latencyByOutcome.HTTP_200_ACCEPTED.p95;http200P99=$l.latencyByOutcome.HTTP_200_ACCEPTED.p99;http200Max=$l.latencyByOutcome.HTTP_200_ACCEPTED.max;http500=$out.HTTP_500_UNCONTROLLED;timeout=$out.CLIENT_TIMEOUT;connectionError=$out.CONNECTION_ERROR;maxInFlight=$l.maxInFlight;dispatcher=$dispatchers;providerTimeline='NOT_AVAILABLE';drainCompleted=$dr.drainCompleted;drainTimeToZeroMs=$dr.timeToZeroMs;initialAiInFlight=$dr.initial.metrics.aiInFlight;finalAiInFlight=$dr.remainingBacklog.aiInFlight;stageMaxInFlight=($s.stages|?{$_.stage -in @('TOKEN','AI','STORAGE')}|%{[ordered]@{stage=$_.stage;maxInFlight=$_.maxInFlight;inFlight=$_.inFlight}})}}
$result|ConvertTo-Json -Depth 30|Set-Content (Join-Path $Root 'aggregate.json') -Encoding UTF8;$result|ConvertTo-Json -Depth 30
